cssCode:
.orb {
  width: 100px;
  height: 100px;
  border-radius: 50%;
  background: radial-gradient(circle, #ff007f, #7928ca);
  box-shadow: 0 0 20px #ff007f, 0 0 60px #7928ca;
  animation: pulseOrb 2s infinite alternate ease-in-out;
}
@keyframes pulseOrb {
  0% { transform: scale(0.8); box-shadow: 0 0 20px #ff007f, 0 0 40px #7928ca; }
  100% { transform: scale(1.2); box-shadow: 0 0 40px #ff007f, 0 0 100px #7928ca; }
}

